function validate(input) {
  const [delay, period, stopTime] = input;
  if (!Number.isInteger(delay) || delay < 20 || delay > 250) return 'delay must be an integer from 20 to 250.';
  if (!Number.isInteger(period) || period < 20 || period > 250) return 'period must be an integer from 20 to 250.';
  if (!Number.isInteger(stopTime) || stopTime < 20 || stopTime > 1000) return 'stopTime must be an integer from 20 to 1000.';
  let time = 0;
  for (let count = 0; time < stopTime; count++) {
    time += delay + period * count;
    if (time === stopTime) return `fn is due exactly at ${stopTime} ms; pick a stopTime between two runs.`;
  }
  return null;
}

