function adapt(input, solve, kit) {
  const [delay, period, stopTime] = input, runs = [];
  if (typeof customClearInterval !== 'function') throw new Error('Define customClearInterval(id) next to customInterval.');
  const clear = customClearInterval, start = Date.now();
  const fn = () => {
    runs.push(Date.now() - start);
    kit.trace(`fn runs (call ${runs.length - 1})`);
  };
  kit.trace(`customInterval(fn, ${delay}, ${period}) is called`);
  const id = solve(fn, delay, period);
  if (typeof id !== 'number') throw new Error('customInterval must return a number id.');
  setTimeout(() => {
    kit.trace(`customClearInterval(${id}) is called`);
    clear(id);
  }, stopTime);
  // Had the clear failed, the next run would come within 1000 ms of stopTime, so wait that long before answering.
  return new Promise(resolve => setTimeout(() => resolve(runs), stopTime + 1000));
}

