const schedules = new Map();
let nextId = 0;

function customInterval(fn, delay, period) {
  const id = nextId++;
  let count = 0;
  const scheduleNext = () => {
    const wait = delay + period * count;
    const timer = setTimeout(() => {
      fn();
      count++;
      scheduleNext();
    }, wait);
    schedules.set(id, timer);
  };
  scheduleNext();
  return id;
}

function customClearInterval(id) {
  clearTimeout(schedules.get(id));
  schedules.delete(id);
}

