const plans = {};
let counter = 1;

function customInterval(fn, delay, period) {
  // Schedule many runs up front at their absolute times; clearing cancels the ones still waiting.
  const id = counter++;
  const timers = [];
  let at = 0;
  for (let count = 0; count < 60; count++) {
    at += delay + period * count;
    timers.push(setTimeout(fn, at));
  }
  plans[id] = timers;
  return id;
}

function customClearInterval(id) {
  for (const timer of plans[id] || []) clearTimeout(timer);
}

