  for (;;) {
    const delay = 20 + Math.floor(rand() * (small ? 81 : 231));
    const period = 20 + Math.floor(rand() * (small ? 81 : 231));
    const stopTime = 20 + Math.floor(rand() * (small ? 381 : 981));
    let time = 0, tie = false;
    for (let count = 0; time < stopTime; count++) {
      time += delay + period * count;
      if (time === stopTime) tie = true;
    }
    if (!tie) return [delay, period, stopTime];
  }
